// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, checkSchema } from '@skyramp/skyramp';
import { getSearch } from './skyrampUtils';

// URL for test requests
const URL = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:8055");

// contract test for /search GET
test('testSearchGet', async () => {
    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    const searchGetResponse = await getSearch(client, URL, headers, "Quantum");
    expect(checkSchema(searchGetResponse, '{"results": [], "total_count": 0}')).toBe(true);
    expect(getValue(searchGetResponse, "total_count")).toBeGreaterThanOrEqual(0);
    expect(getValue(searchGetResponse, "results").length).toBeLessThanOrEqual(20);
    expect(getValue(searchGetResponse, "errors")).toBeUndefined();
});
